 5	function esc(value: string): string { return value.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n"); }
 6	function localStamp(value: string, timezone: string): string {
 7	  const parts = new Intl.DateTimeFormat("en", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" }).formatToParts(new Date(value));
 8	  const get = (type: string) => parts.find((part) => part.type === type)?.value ?? "00";
 9	  return `${get("year")}${get("month")}${get("day")}T${get("hour")}${get("minute")}${get("second")}`;
10	}
11	export function generateICS(input: { interview: Pick<Interview, "title" | "startsAt" | "endsAt" | "timezone" | "locationOrLink">; application: Pick<Application, "company" | "position" | "jobUrl"> }): string {
12	  const { interview, application } = input;
13	  const lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Local Career Workspace//EN", "BEGIN:VEVENT", `UID:${crypto.randomUUID()}`, `SUMMARY:${esc(`${interview.title} - ${application.company} / ${application.position}`)}`, `DTSTART;TZID=${esc(interview.timezone)}:${localStamp(interview.startsAt, interview.timezone)}`];
14	  if (interview.endsAt) lines.push(`DTEND;TZID=${esc(interview.timezone)}:${localStamp(interview.endsAt, interview.timezone)}`);
15	  if (interview.locationOrLink) lines.push(`LOCATION:${esc(interview.locationOrLink)}`);
16	  if (application.jobUrl) lines.push(`URL:${esc(application.jobUrl)}`);
17	  lines.push(`DESCRIPTION:${esc(`${application.company} / ${application.position}`)}`, "END:VEVENT", "END:VCALENDAR");
18	  return `${lines.join("\r\n")}\r\n`;
19	}
